def scan(name, t):
    # rows and cols with norm ratio to median
    out=[]
    for dim,label in [(0,'row'),(1,'col')]:
        n=t.norm(dim=dim)
        med=n.median()
        if med==0: continue
        ratio=n/med
        idx=(ratio<0.02).nonzero().flatten().tolist()
        if idx: out.append((label, [int(i) for i in idx], round(float(med),3)))
    return out
